def semver_sort(versions):
    def parse_key(v):
        # strip build metadata
        main = v.split('+', 1)[0]
        # split main version from prerelease at first '-'
        if '-' in main:
            core, pre = main.split('-', 1)
        else:
            core, pre = main, None

        major, minor, patch = (int(x) for x in core.split('.'))

        if pre is None:
            has_pre = 1  # no prerelease sorts after
            pre_ids = ()
        else:
            has_pre = 0  # has prerelease sorts before
            parts = pre.split('.')
            pre_ids = []
            for p in parts:
                if p.isdigit():
                    pre_ids.append((0, int(p), ''))
                else:
                    pre_ids.append((1, 0, p))
            pre_ids = tuple(pre_ids)

        return (major, minor, patch, has_pre, pre_ids, len(pre_ids))

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda iv: (parse_key(iv[1]), iv[0]))
    return [v for i, v in indexed]

